import { PureContainerBase } from "./PureContainer";
import { isArray } from "../util/isArray";
export class IsolatedScope extends PureContainerBase {
    declareData(...args) {
        return super.declareData(...args, {
            data: { structured: true },
        });
    }
    init() {
        if (typeof this.bind === "string")
            this.data = { bind: this.bind };
        else if (isArray(this.bind)) {
            let data = {};
            this.bind.forEach((x, i) => {
                data[String(i)] = { bind: x };
            });
            this.data = data;
        }
        super.init();
    }
    explore(context, instance) {
        if (instance.shouldUpdate) {
            super.explore(context, instance);
        }
        else if (instance.children) {
            // mark children to prevent sweeping them away
            for (let i = 0; i < instance.children.length; i++)
                instance.instanceCache.addChild(instance.children[i]);
        }
    }
}
